"""Generate the native version lookup from the single reviewed JSON catalog."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    data = json.loads((ROOT / "data/versions/hut.json").read_text())
    rows = []
    for r in data["intervals"]:
        s = r["screen"]
        for v in r["versions"]:
            pre262 = int(s["reference_terrain_profile"] != "26.3")
            rows.append(f'{{"{v}",{pre262}}},')
    text = (
        "// Generated by tools/generate_hut_versions.py\n#pragma once\nstruct HutVersionConfig {const char* name;bool pre262;};\nstatic constexpr HutVersionConfig hutVersionConfigs[]={\n"
        + "\n".join(rows)
        + "\n};\n"
    )
    target = ROOT / "native/hut_versions.generated.h"
    if not target.exists() or target.read_text() != text:
        target.write_text(text)


if __name__ == "__main__":
    main()
